    }
  },
  "relationships": [
    {"type": "HOLDS_LICENCE", "from_role": "subject", "to_role": "licence", "rationale": "The licensee named in 'Licensee Name' holds the licence described by Licence Number / Grade / Class."}
  ],
  "new_rules": [
    {"source_paths": ["Licence Type CODE"], "join_with": " ", "target": "ext.entity.holder_kind",
     "steps": [{"op": "trim", "args": {}}, {"op": "upper", "args": {}}, {"op": "map_enum", "args": {"mapping": {"I": "individual", "C": "organisation"}, "default": "unknown"}}],
     "confidence": 0.9,
     "rationale": "Reviewer P1 #1: 'Licence Type CODE' states whether the licensee is an individual (I, 474/508) or a company (C, 34/508). Recorded as matching evidence in holder_kind; it never implies sole_trader, and the approved entity_type rule still maps I to 'unknown'. Corroborated by Licence Type DESC: 100% of I rows are 'Individual' and 100% of C rows are 'Company' in the discovery partition."},
    {"source_paths": ["Licence Number"], "join_with": " ", "target": "ext.licence.number",
     "steps": [{"op": "trim", "args": {}}, {"op": "null_if", "args": {"values": ["", "-"]}}],
     "entity": "licence", "confidence": 0.95,
     "rationale": "Publisher-assigned licence number, 100% present, identifies the licence across snapshots (506 distinct for 508 rows; the two duplicate numbers are the same holder holding two licences with one number - a source quirk, not a mapping error)."},
    {"source_paths": ["Licence Grade"], "join_with": " ", "target": "ext.licence.grade",
     "steps": [{"op": "trim", "args": {}}, {"op": "collapse_whitespace", "args": {}}],
     "entity": "licence", "confidence": 0.9,
     "rationale": "QBCC licence grade, six source-stated licence kinds: Trade Contractor Licence (462), Site Supervisor (23), Fire Occupational (9), Nominee Supervisor (7), Building Designer Licence (4), Mechanical Services Occupational (3)."},
    {"source_paths": ["Licence Class Type"], "join_with": " ", "target": "ext.licence.class",
     "entity": "licence", "confidence": 0.9,
     "steps": [{"op": "trim", "args": {}}, {"op": "collapse_whitespace", "args": {}}],
     "rationale": "Reviewer P1 #2 with critic fix: Licence Class Type is the licensed trade in the publisher's own wording (Carpentry, Plumbing and Drainage, Joinery, ...; 57 distinct, 100% present). Each whole cell is ONE observation: the comma in names like 'Fire Detection, Alarm and Warning Systems - Occupational' is part of a single QBCC class, not a delimiter, and splitting on ', ' fabricated classes on held-out record 70329. The static UNSPLIT_LIST_VALUES check is knowingly left unsatisfied: probes showed it is only cleared by a ', ' split whose output the held-out critic proved wrong, so correctness wins over the heuristic (flagged for the reviewer). No split step is included."}
  ],
  "unmapped": [
    {"source_path": "_id", "reason": "CKAN datastore row id for the licence record, not a business identifier; used only as record_id."},
    {"source_path": "Licence Type DESC", "reason": "Human-readable duplicate of Licence Type CODE ('Individual'/'Company'); CODE feeds entity.entity_type (approved rule 3) and ext.entity.holder_kind. Verified, not assumed: in the discovery partition 100% of I rows are described 'Individual' and 100% of C rows 'Company', so no row contradicts the code-derived holder_kind."},
